"""Tests for ledgerlock/format.py."""

from __future__ import annotations

import hashlib
import json
import unittest

from ledgerlock import format


class CanonicalBytesTests(unittest.TestCase):
    def test_matches_json_dumps_with_frozen_params(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        self.assertEqual(
            format.canonical_bytes(line),
            json.dumps(
                line,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
            ).encode("utf-8"),
        )

    def test_byte_stable_across_calls(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        self.assertEqual(format.canonical_bytes(line), format.canonical_bytes(line))

    def test_non_ascii_uses_utf8_literal(self):
        line = {"key": "é"}
        out = format.canonical_bytes(line)
        self.assertIn(b"\xc3\xa9", out)
        self.assertNotIn(b"\\u00e9", out)
        self.assertEqual(out, format.canonical_bytes(line))

    def test_key_insertion_order_irrelevant(self):
        a = {"a": 1, "b": 2, "c": 3}
        b = {"c": 3, "b": 2, "a": 1}
        self.assertEqual(format.canonical_bytes(a), format.canonical_bytes(b))

    def test_genesis_is_literal_seven_char_string(self):
        self.assertEqual(format.GENESIS, "GENESIS")
        self.assertEqual(len(format.GENESIS), 7)
        self.assertNotEqual(format.GENESIS, "0" * 64)

    def test_roundtrip_through_json_loads(self):
        original = {"op": "put", "key": "k", "value": {"nested": [1, 2]}, "ts": 1}
        first = format.canonical_bytes(original)
        reloaded = json.loads(first.decode("utf-8"))
        self.assertEqual(format.canonical_bytes(reloaded), first)


class LineHashTests(unittest.TestCase):
    def test_returns_64_lowercase_hex(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        digest = format.line_hash(format.GENESIS, line)
        self.assertEqual(len(digest), 64)
        self.assertTrue(all(c in "0123456789abcdef" for c in digest))

    def test_different_prev_hash_yields_different_digest(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        a = format.line_hash("a" * 64, line)
        b = format.line_hash("b" * 64, line)
        self.assertNotEqual(a, b)

    def test_ignores_existing_hash_and_prev_hash_fields(self):
        line = {
            "op": "put",
            "key": "k",
            "value": "v",
            "ts": 1,
            "id": "r",
            "hash": "deadbeef" * 8,
            "prev_hash": "feedface" * 8,
        }
        clean = {
            "op": "put",
            "key": "k",
            "value": "v",
            "ts": 1,
            "id": "r",
        }
        self.assertEqual(
            format.line_hash(format.GENESIS, line),
            format.line_hash(format.GENESIS, clean),
        )

    def test_deterministic_across_calls(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        prev = "a" * 64
        self.assertEqual(format.line_hash(prev, line), format.line_hash(prev, line))

    def test_genesis_is_accepted(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        # Must not raise.
        digest = format.line_hash(format.GENESIS, line)
        # And it must equal a hand-computed SHA-256.
        expected = hashlib.sha256(
            (format.GENESIS + "|" + json.dumps(
                line,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
            )).encode("utf-8")
        ).hexdigest()
        self.assertEqual(digest, expected)


class NormalizeKeyTests(unittest.TestCase):
    def test_passthrough_for_ascii(self):
        self.assertEqual(format.normalize_key("hello"), "hello")

    def test_nfc_form_is_unaffected(self):
        self.assertEqual(format.normalize_key("é"), "é")

    def test_nfd_collapses_to_nfc(self):
        nfc = "\u00e9"
        nfd = "e\u0301"
        self.assertEqual(format.normalize_key(nfc), format.normalize_key(nfd))
        self.assertEqual(format.normalize_key(nfd), nfc)


if __name__ == "__main__":
    unittest.main()

